import {
  CacheFirst,
  ExpirationPlugin,
  NetworkFirst,
  RangeRequestsPlugin,
  Serwist,
  StaleWhileRevalidate,
} from 'serwist';

const isSameOrigin = (url) => self.origin === url.origin;

// Replaces the runtime caching rules that next-pwa generated by default, so
// the service worker keeps caching exactly the same requests the same way.
const runtimeCaching = [
  {
    matcher: '/',
    method: 'GET',
    handler: new NetworkFirst({
      cacheName: 'start-url',
      plugins: [
        {
          cacheWillUpdate: async ({ response }) =>
            response && response.type === 'opaqueredirect'
              ? new Response(response.body, {
                  status: 200,
                  statusText: 'OK',
                  headers: response.headers,
                })
              : response,
        },
      ],
    }),
  },
  {
    matcher: /^https:\/\/fonts\.(?:gstatic)\.com\/.*/i,
    method: 'GET',
    handler: new CacheFirst({
      cacheName: 'google-fonts-webfonts',
      plugins: [
        new ExpirationPlugin({ maxEntries: 4, maxAgeSeconds: 31536000 }),
      ],
    }),
  },
  {
    matcher: /^https:\/\/fonts\.(?:googleapis)\.com\/.*/i,
    method: 'GET',
    handler: new StaleWhileRevalidate({
      cacheName: 'google-fonts-stylesheets',
      plugins: [new ExpirationPlugin({ maxEntries: 4, maxAgeSeconds: 604800 })],
    }),
  },
  {
    matcher: /\.(?:eot|otf|ttc|ttf|woff|woff2|font.css)$/i,
    method: 'GET',
    handler: new StaleWhileRevalidate({
      cacheName: 'static-font-assets',
      plugins: [new ExpirationPlugin({ maxEntries: 4, maxAgeSeconds: 604800 })],
    }),
  },
  {
    matcher: /\.(?:jpg|jpeg|gif|png|svg|ico|webp)$/i,
    method: 'GET',
    handler: new StaleWhileRevalidate({
      cacheName: 'static-image-assets',
      plugins: [new ExpirationPlugin({ maxEntries: 64, maxAgeSeconds: 86400 })],
    }),
  },
  {
    matcher: /\/_next\/image\?url=.+$/i,
    method: 'GET',
    handler: new StaleWhileRevalidate({
      cacheName: 'next-image',
      plugins: [new ExpirationPlugin({ maxEntries: 64, maxAgeSeconds: 86400 })],
    }),
  },
  {
    matcher: /\.(?:mp3|wav|ogg)$/i,
    method: 'GET',
    handler: new CacheFirst({
      cacheName: 'static-audio-assets',
      plugins: [
        new RangeRequestsPlugin(),
        new ExpirationPlugin({ maxEntries: 32, maxAgeSeconds: 86400 }),
      ],
    }),
  },
  {
    matcher: /\.(?:mp4)$/i,
    method: 'GET',
    handler: new CacheFirst({
      cacheName: 'static-video-assets',
      plugins: [
        new RangeRequestsPlugin(),
        new ExpirationPlugin({ maxEntries: 32, maxAgeSeconds: 86400 }),
      ],
    }),
  },
  {
    matcher: /\.(?:js)$/i,
    method: 'GET',
    handler: new StaleWhileRevalidate({
      cacheName: 'static-js-assets',
      plugins: [new ExpirationPlugin({ maxEntries: 32, maxAgeSeconds: 86400 })],
    }),
  },
  {
    matcher: /\.(?:css|less)$/i,
    method: 'GET',
    handler: new StaleWhileRevalidate({
      cacheName: 'static-style-assets',
      plugins: [new ExpirationPlugin({ maxEntries: 32, maxAgeSeconds: 86400 })],
    }),
  },
  {
    matcher: /\/_next\/data\/.+\/.+\.json$/i,
    method: 'GET',
    handler: new StaleWhileRevalidate({
      cacheName: 'next-data',
      plugins: [new ExpirationPlugin({ maxEntries: 32, maxAgeSeconds: 86400 })],
    }),
  },
  {
    matcher: /\.(?:json|xml|csv)$/i,
    method: 'GET',
    handler: new NetworkFirst({
      cacheName: 'static-data-assets',
      plugins: [new ExpirationPlugin({ maxEntries: 32, maxAgeSeconds: 86400 })],
    }),
  },
  {
    matcher: ({ url }) =>
      isSameOrigin(url) &&
      !url.pathname.startsWith('/api/auth/') &&
      url.pathname.startsWith('/api/'),
    method: 'GET',
    handler: new NetworkFirst({
      cacheName: 'apis',
      networkTimeoutSeconds: 10,
      plugins: [new ExpirationPlugin({ maxEntries: 16, maxAgeSeconds: 86400 })],
    }),
  },
  {
    matcher: ({ url }) =>
      isSameOrigin(url) && !url.pathname.startsWith('/api/'),
    method: 'GET',
    handler: new NetworkFirst({
      cacheName: 'others',
      networkTimeoutSeconds: 10,
      plugins: [new ExpirationPlugin({ maxEntries: 32, maxAgeSeconds: 86400 })],
    }),
  },
  {
    matcher: ({ url }) => !isSameOrigin(url),
    method: 'GET',
    handler: new NetworkFirst({
      cacheName: 'cross-origin',
      networkTimeoutSeconds: 10,
      plugins: [new ExpirationPlugin({ maxEntries: 32, maxAgeSeconds: 3600 })],
    }),
  },
];

const serwist = new Serwist({
  precacheEntries: self.__SW_MANIFEST,
  precacheOptions: {
    cleanupOutdatedCaches: true,
    ignoreURLParametersMatching: [],
  },
  skipWaiting: true,
  clientsClaim: true,
  runtimeCaching,
});

serwist.addEventListeners();
